# FINANCE_DB_URL points at the Postgres database holding account_holders (e.g. neurostack_dev).
# Falls back to a local finance.db SQLite file only when the env var is unset (local dev without Postgres access).
current_dir = os.path.dirname(os.path.abspath(__file__))
default_db_path = os.path.join(current_dir, "..", "examples", "finance.db")
FINANCE_DB_URL = os.getenv("DATABASE_URL", f"sqlite:///{default_db_path}")

_engine = None

def get_engine():
    """Lazy-load the SQLAlchemy database engine."""
    global _engine
    if _engine is None:
        _engine = create_engine(FINANCE_DB_URL, pool_size=5, max_overflow=10)
    return _engine

def _execute(query: str, params: tuple = ()) -> list[dict]:
    # Seamlessly adapt '?' placeholder queries to SQLAlchemy named parameter mapping
    engine = get_engine()
    
    param_dict = {}
    param_count = 0
    while "?" in query:
        placeholder = f":p{param_count}"
        query = query.replace("?", placeholder, 1)
        if param_count < len(params):
            param_dict[f"p{param_count}"] = params[param_count]
        param_count += 1
        
    with engine.connect() as conn:
        result = conn.execute(text(query), param_dict)
        return [dict(row._mapping) for row in result]

def _get_role(tool_context: Any) -> str:
    """Helper to extract user role from tool context."""
    if not tool_context or not hasattr(tool_context, "state"):
        return "user"
    return tool_context.state.get("user_metadata", {}).get("role", "user")

