def get_account_holder_names(filter_name: str | None = None) -> Dict[str, Any]:
    """Returns a list of account holder names. Only names are returned."""
    query = "SELECT account_holder_name FROM account_holders"
    params = []
    if filter_name:
        query += " WHERE LOWER(account_holder_name) LIKE LOWER(?)"
        params.append(f"%{filter_name}%")
    
    rows = _execute(query, tuple(params))
    return {
        "status": "success",
        "data": [{"account_holder_name": r["account_holder_name"]} for r in rows]
    }

