def get_account_ids(account_holder_name: str | None = None, tool_context: Any = None) -> Dict[str, Any]:
    """
    Returns account IDs. 
    Note: For 'user' and 'developer' roles, the IDs are masked with asterisks.
    For 'admin' role, full IDs are shown.
    """
    role = _get_role(tool_context)
    query = "SELECT account_holder_name, account_id FROM account_holders"
    params = []
    if account_holder_name:
        query += " WHERE LOWER(account_holder_name) LIKE LOWER(?)"
        params.append(f"%{account_holder_name}%")
        
    rows = _execute(query, tuple(params))
    
    data = []
    for r in rows:
        row_dict = dict(r)
        if role in ["user", "developer"]:
            # Masking logic
            raw_id = row_dict["account_id"]
            if "-" in raw_id:
                parts = raw_id.split("-")
                row_dict["account_id"] = f"{parts[0]}-***-***"
            else:
                row_dict["account_id"] = "***-***"
        data.append(row_dict)
        
    return {
        "status": "success",
        "data": data,
        "note": "Account IDs are masked for your role." if role != "admin" else "Clear text IDs shown for admin."
    }

